"""Artist credits for YouTube's auto-generated art tracks, read on the
hosted site itself rather than relayed from the Pi's yt-dlp."""

from pathlib import Path

import httpx

from meshradio.config import CacheConfig
from meshradio.media import cacher as cacher_mod
from meshradio.media import metadata
from meshradio.media.cacher import Cacher

from .helpers import art_track_description, make_pending_track, watch_page


def test_credits_are_read_from_an_art_track_description():
    desc = art_track_description("Song", ("Artist A",))
    assert metadata.parse_art_track_artists(desc) == "Artist A"


def test_every_credited_artist_is_kept_in_order():
    desc = art_track_description("Song", ("Artist A", "Artist B"))
    assert metadata.parse_art_track_artists(desc) == "Artist A, Artist B"


def test_a_description_youtube_did_not_write_is_left_alone():
    # Someone's own text that happens to use a middle dot.
    assert metadata.parse_art_track_artists("Song · Me\n\nfollow me!") is None
    # The right opening without YouTube's closing line.
    assert metadata.parse_art_track_artists(
        "Provided to YouTube by X\n\nSong · Artist\n\nAlbum"
    ) is None
    # The right frame, but no artist after the title.
    assert metadata.parse_art_track_artists(
        "Provided to YouTube by X\n\nSong\n\nAlbum\n\nAuto-generated by YouTube."
    ) is None
    assert metadata.parse_art_track_artists("") is None
    assert metadata.parse_art_track_artists(None) is None


def test_the_description_is_read_out_of_the_watch_page():
    desc = art_track_description("Song \"Quoted\"", ("Björk",))
    assert metadata.parse_watch_description(watch_page(desc)) == desc
    assert metadata.parse_watch_description("<html>consent wall</html>") is None


async def test_watch_credits_come_from_one_page_fetch():
    seen = []

    def handler(request):
        seen.append(request.url.params["v"])
        return httpx.Response(200, text=watch_page(art_track_description("S", ("A", "B"))))

    async with httpx.AsyncClient(transport=httpx.MockTransport(handler)) as client:
        assert await metadata.fetch_watch_credits("aaaaaaaaaaa", client) == "A, B"
        # The length lookup reads the same page.
        assert await metadata.fetch_duration("aaaaaaaaaaa", client) == 200.0
    assert seen == ["aaaaaaaaaaa", "aaaaaaaaaaa"]


async def test_a_refused_watch_page_gives_no_credits():
    def handler(request):
        return httpx.Response(429)

    async with httpx.AsyncClient(transport=httpx.MockTransport(handler)) as client:
        assert await metadata.fetch_watch_credits("aaaaaaaaaaa", client) is None


def _embed_cacher(db, bus, tmp_path, monkeypatch, channel, credits):
    calls = []

    async def fake_oembed(video_id, client=None):
        return {"title": "Song", "artist": channel, "thumbnail": ""}

    async def fake_credits(video_id, client=None):
        calls.append(video_id)
        return credits

    monkeypatch.setattr(cacher_mod.metadata, "fetch_oembed", fake_oembed)
    monkeypatch.setattr(cacher_mod.metadata, "fetch_watch_credits", fake_credits)
    return Cacher(CacheConfig(), Path(tmp_path), db, bus, embed=True), calls


async def test_a_release_topic_song_gets_its_credited_artist(db, bus, monkeypatch, tmp_path):
    c, calls = _embed_cacher(db, bus, tmp_path, monkeypatch, "Release - Topic", "Real Artist")
    track = await make_pending_track(db, "aaaaaaaaaaa")
    await c.process_track(track)
    row = await db.track_by_id(track["id"])
    assert row["artist"] == "Real Artist"
    assert row["cache_status"] == "ready"
    assert calls == ["aaaaaaaaaaa"]


async def test_a_song_with_no_channel_name_is_looked_up_too(db, bus, monkeypatch, tmp_path):
    c, calls = _embed_cacher(db, bus, tmp_path, monkeypatch, "", "Real Artist")
    track = await make_pending_track(db, "aaaaaaaaaaa")
    await c.process_track(track)
    assert (await db.track_by_id(track["id"]))["artist"] == "Real Artist"


async def test_a_real_channel_name_is_kept_without_a_lookup(db, bus, monkeypatch, tmp_path):
    c, calls = _embed_cacher(db, bus, tmp_path, monkeypatch, "Artist A", "Someone Else")
    track = await make_pending_track(db, "aaaaaaaaaaa")
    await c.process_track(track)
    assert (await db.track_by_id(track["id"]))["artist"] == "Artist A"
    assert calls == []


async def test_no_credits_leaves_the_song_for_fix_artists(db, bus, monkeypatch, tmp_path):
    c, _ = _embed_cacher(db, bus, tmp_path, monkeypatch, "Release - Topic", None)
    track = await make_pending_track(db, "aaaaaaaaaaa")
    await c.process_track(track)
    row = await db.track_by_id(track["id"])
    assert row["artist"] is None          # the stand-in is stored as no artist
    assert row["cache_status"] == "ready"  # the song still plays
    assert row["video_id"] in {s["video_id"] for s in await db.songs_to_fix()}
